#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the path matrix.
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       path[i][j] = i*j%7+1;
 *       if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
 *          path[i][j] = 999;
 *     }
 *
 * C array path[i][j] is mapped to Buffer(j, i).
 */
static void init_array(int n, Buffer<num_t, 2> path) {
    Var i("i"), j("j");
    Func init_path("init_path");

    // Base value: i * j % 7 + 1
    Expr base = cast<num_t>((i * j % 7) + 1);

    // Condition for setting to 999
    Expr sum = i + j;
    Expr cond = ((sum % 13) == 0) ||
                ((sum % 7)  == 0) ||
                ((sum % 11) == 0);

    // C: path[i][j] -> Buffer(j, i)
    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             base);

    // --- Schedule for initialization ---------------------------------
    // Tile the (j,i) space, vectorize along j (contiguous in memory),
    // and parallelize over tiles in i for good cache use and CPU usage.
    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    const Type t = type_of<num_t>();
    const int vec_width = natural_vector_size(t); // uses host target features

    init_path
        .tile(j, i, jo, io, ji, ii, 128, 32) // 128 x-columns, 32 rows per tile
        .parallel(io);                       // parallelize over tiles in i (rows)

    if (vec_width > 1) {
        init_path.vectorize(ji, vec_width);  // vectorize across contiguous j
    }
    // -----------------------------------------------------------------

    // Realize into the provided buffer. Buffer layout is (x=j, y=i).
    init_path.realize(path);
